  1	/**
  2	 * GUI HTTP Server
  3	 *
  4	 * Standalone Node.js HTTP server that routes requests to API handlers
  5	 * (gui/api.ts) and serves static files from gui/public/. This is a SEPARATE
  6	 * process from the MCP server — stdout logging is allowed and expected.
  7	 *
  8	 * CLI Arguments:
  9	 *   --port <n>           Listen port (default: 3420)
 10	 *   --ledger-dir <path>  Ledger root path (handled by resolveLedgerRoot())
 11	 */
 12	
 13	import { createServer } from 'node:http';
 14	import type { IncomingMessage, ServerResponse } from 'node:http';
 15	import { readFile } from 'node:fs/promises';
 16	import { join, extname, dirname, resolve } from 'node:path';
 17	import { fileURLToPath } from 'node:url';
 18	
 19	import { resolveLedgerRoot, resolveProjectDir, ORCHESTRATOR_LOGS_DIR, WORKSPACE_ROOT } from '../src/utils/ledger-root.js';
 20	import { SAFE_SLUG_REGEX } from '../src/utils/constants.js';
 21	import { captureWorkspaceVersions } from '../src/utils/workspace-versions.js';
 22	import type { WorkspaceVersions } from '../src/utils/workspace-versions.js';
 23	import { readConfigFromDisk, startConfigWatcher } from '../src/gui/config.js';
 24	import { startAutoArchiveTimer } from '../src/gui/auto-archive.js';
 25	import {
 26	  handleListRunLogs,
 27	  handleGetRunLog,
 28	} from '../src/gui/handlers/run-log-handlers.js';
 29	import {
 30	  handleListProjects,
 31	  handleGetProject,
 32	  handleGetPlanDocument,
 33	  handleGetSynthesisDocument,
 34	  handleListWorkPackages,
 35	  handleGetWorkPackage,
 36	  handleDeleteProject,
 37	  handleGetInsights,
 38	  handleGetConfig,
 39	  handleUpdateConfig,
 40	  handleResetProject,
 41	  handleGetProjectHealth,
 42	  handleGetWorkPackageOverview,
 43	  handleRenameProject,
 44	  handleArchiveProject,
 45	  handleUnarchiveProject,
 46	  handleMarkProjectComplete,
 47	  handleListDialogues,
 48	  handleGetDialogueFile,
 49	  handleListChunks,
 50	  handleGetChunkFile,
 51	  handleOrchestratorStart,
 52	  handleGetOrchestratorQueue,
 53	  handleOrchestratorKill,
 54	  handleOrchestratorDismiss,
 55	  handleGetRunStatus,
 56	  ApiError,
 57	} from './api.js';
 58	import { renderChunksToMarkdown } from './chunk-renderer.js';
 59	
 60	// ---------------------------------------------------------------------------
 61	// Path resolution (ESM-safe)
 62	// ---------------------------------------------------------------------------
 63	
 64	const __filename = fileURLToPath(import.meta.url);
 65	const __dirname = dirname(__filename);
 66	
 67	const PUBLIC_DIR = join(__dirname, 'public');
 68	
 69	// ---------------------------------------------------------------------------
 70	// CLI argument parsing
 71	// ---------------------------------------------------------------------------
 72	
 73	function getPort(): number {
 74	  const args = process.argv;
 75	  const idx = args.indexOf('--port');
 76	  if (idx !== -1 && idx + 1 < args.length) {
 77	    const p = parseInt(args[idx + 1]!, 10);
 78	    if (!isNaN(p) && p > 0) return p;
 79	  }
 80	  return 3420;
 81	}
 82	
 83	// ---------------------------------------------------------------------------
 84	// MIME types
 85	// ---------------------------------------------------------------------------
 86	
 87	const MIME_TYPES: Record<string, string> = {
 88	  '.html': 'text/html',
 89	  '.css': 'text/css',
 90	  '.js': 'application/javascript',
 91	};
 92	
 93	// ---------------------------------------------------------------------------
 94	// CORS helpers
 95	// ---------------------------------------------------------------------------
 96	
 97	function corsHeaders(port: number): Record<string, string> {
 98	  return {
 99	    'Access-Control-Allow-Origin': `http://localhost:${port}`,
100	    'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',

101	    'Access-Control-Allow-Headers': 'Content-Type',
102	  };
103	}
104	
105	// ---------------------------------------------------------------------------
106	// Security headers
107	// ---------------------------------------------------------------------------
108	
109	function securityHeaders(): Record<string, string> {
110	  return {
111	    'X-Content-Type-Options': 'nosniff',
112	    'X-Frame-Options': 'DENY',
113	    'Referrer-Policy': 'strict-origin-when-cross-origin',
114	    'Content-Security-Policy':
115	      "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'",
116	  };
117	}
118	
119	// ---------------------------------------------------------------------------
120	// Response helpers
121	// ---------------------------------------------------------------------------
122	
123	function sendJson(
124	  res: ServerResponse,
125	  status: number,
126	  data: unknown,
127	  port: number
128	): void {
129	  const body = JSON.stringify(data);
130	  res.writeHead(status, {
131	    'Content-Type': 'application/json',
132	    'Content-Length': Buffer.byteLength(body),
133	    ...corsHeaders(port),
134	    ...securityHeaders(),
135	  });
136	  res.end(body);
137	}
138	
139	function sendError(
140	  res: ServerResponse,
141	  status: number,
142	  code: string,
143	  message: string,
144	  port: number
145	): void {
146	  sendJson(res, status, { error: { code, message } }, port);
147	}
148	
149	export function apiErrorToStatus(code: string): number {
150	  switch (code) {
151	    case 'NOT_FOUND':
152	      return 404;
153	    case 'FORBIDDEN':
154	      return 403;
155	    case 'VALIDATION_ERROR':
156	      return 400;
157	    case 'CONFLICT':
158	      return 409;
159	    default:
160	      return 500;
161	  }
162	}
163	
164	// ---------------------------------------------------------------------------
165	// Body reading
166	// ---------------------------------------------------------------------------
167	
168	/** Maximum accepted request body size (1 MiB). */
169	export const MAX_BODY_BYTES = 1_048_576;
170	
171	/** Thrown by {@link readBody} when the request body exceeds {@link MAX_BODY_BYTES}. */
172	export class PayloadTooLargeError extends Error {
173	  constructor() {
174	    super('Payload Too Large');
175	    this.name = 'PayloadTooLargeError';
176	  }
177	}
178	
179	/**
180	 * Reads the full request body as a UTF-8 string, enforcing a size limit of
181	 * {@link MAX_BODY_BYTES} (1 MiB).
182	 *
183	 * @throws {PayloadTooLargeError} When the body exceeds the limit (detected
184	 *   either via Content-Length header pre-check or streaming byte count).
185	 *   **Callers must catch this error and return a 413 response.**
186	 *
187	 * @param req - The incoming HTTP request.
188	 * @returns The full body string.
189	 */
190	function readBody(req: IncomingMessage): Promise<string> {
191	  return new Promise((resolve, reject) => {
192	    // Content-Length pre-check: reject immediately if the declared size exceeds the limit.
193	    const declaredLength = req.headers['content-length'];
194	    if (declaredLength !== undefined) {
195	      const n = parseInt(declaredLength, 10);
196	      if (!isNaN(n) && n > MAX_BODY_BYTES) {
197	        req.resume();  // drain body data from socket buffer
198	        reject(new PayloadTooLargeError());
199	        return;
200	      }
201	    }
202	
203	    const chunks: Buffer[] = [];
204	    let totalBytes = 0;
205	    let rejected = false;
206	
207	    req.on('data', (chunk: Buffer) => {
208	      if (rejected) return;
209	      totalBytes += chunk.length;
210	      if (totalBytes > MAX_BODY_BYTES) {
211	        rejected = true;
212	        reject(new PayloadTooLargeError());
213	        // Drain remaining data so the 413 response can be sent cleanly.
214	        req.resume();
215	        return;
216	      }
217	      chunks.push(chunk);
218	    });
219	    req.on('end', () => {
220	      if (!rejected) resolve(Buffer.concat(chunks).toString('utf-8'));
221	    });
222	    req.on('error', (err) => {
223	      if (!rejected) reject(err);
224	    });
225	  });
226	}
227	
228	/**
229	 * Reads and parses the request body as JSON, enforcing the same size limit as
230	 * {@link readBody}. Throws {@link PayloadTooLargeError} for oversized bodies
231	 * and {@link ApiError} with code `VALIDATION_ERROR` for invalid JSON.
232	 *
233	 * @param req - The incoming HTTP request.
234	 * @returns The parsed JSON value.
235	 */
236	async function readJsonBody(req: IncomingMessage): Promise<unknown> {
237	  const raw = await readBody(req);
238	  try {
239	    return JSON.parse(raw);
240	  } catch {
241	    throw new ApiError('VALIDATION_ERROR', 'Invalid JSON body.');
242	  }
243	}
244	
245	// ---------------------------------------------------------------------------
246	// Router
247	// ---------------------------------------------------------------------------
248	
249	type RouteHandler = () => Promise<unknown>;
250	
251	// ---------------------------------------------------------------------------
252	// Meta helpers
253	// ---------------------------------------------------------------------------
254	
255	/**
256	 * Guards against path-traversal attacks on URL parameters that are used as
257	 * filesystem path segments.
258	 *
259	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
260	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
261	 * callers receive the same status as a missing project — no information leak.
262	 *
263	 * @param segment - The raw URL parameter value to validate.
264	 */
265	function assertSafeSlug(segment: string): void {
266	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
267	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
268	  }
269	}
270	
271	/**
272	 * Reads the `.meta.json` for a namespaced project at
273	 * `{ledgerRoot}/{repoUrlParam}/{slugUrlParam}/.meta.json`.
274	 *
275	 * Returns the stored `repository_name` value, falling back to `repoUrlParam`
276	 * when the field is absent or null.
277	 *
278	 * When the meta file exists but contains malformed JSON, the function still
279	 * falls back to `repoUrlParam` — but writes a warning to `process.stderr`
280	 * (format: `[server] Warning: malformed .meta.json at {path} — falling back
281	 * to URL param '…'`) so operators can detect corrupt meta files during
282	 * troubleshooting. API callers always receive the fallback value in this case.
283	 *
284	 * Throws {@link ApiError} `NOT_FOUND` when the meta file does not exist —
285	 * indicating that the `{repo}/{slug}` combination is not a known project in
286	 * this ledger. This is the project-existence check for namespaced routes.
287	 * Using `NOT_FOUND` (rather than a 400 or `VALIDATION_ERROR`) is intentional
288	 * information-hiding: invalid-input and missing-project cases are
289	 * indistinguishable from the client side.
290	 *
291	 * Both `repoUrlParam` and `slugUrlParam` are validated via {@link assertSafeSlug}
292	 * before any filesystem access is attempted (defence-in-depth).
293	 */
294	export async function resolveRepoName(
295	  ledgerRoot: string,
296	  repoUrlParam: string,
297	  slugUrlParam: string,
298	): Promise<string> {
299	  assertSafeSlug(repoUrlParam);
300	  assertSafeSlug(slugUrlParam);

301	  const metaPath = join(ledgerRoot, repoUrlParam, slugUrlParam, '.meta.json');
302	  let raw: string;
303	  try {
304	    raw = await readFile(metaPath, 'utf-8');
305	  } catch {
306	    throw new ApiError('NOT_FOUND', `Project not found: ${slugUrlParam}`);
307	  }
308	  try {
309	    const meta = JSON.parse(raw) as { repository_name?: string | null };
310	    return meta.repository_name ?? repoUrlParam;
311	  } catch {
312	    // Malformed .meta.json — project directory exists, fall back to URL param.
313	    // Log to stderr so operators can detect corrupt meta files during troubleshooting.
314	    process.stderr.write(`[server] Warning: malformed .meta.json at ${metaPath} — falling back to URL param '${repoUrlParam}'\n`);
315	    return repoUrlParam;
316	  }
317	}
318	
319	/**
320	 * Matches a method + URL path to an API handler.
321	 * Returns a handler thunk or null if no route matches.
322	 */
323	function matchRoute(
324	  method: string,
325	  url: string,
326	  ledgerRoot: string,
327	  orchestratorLogsDir: string
328	): RouteHandler | null {
329	  const [path] = url.split('?') as [string];
330	  const segments = path.split('/').filter(Boolean);
331	
332	  // All API routes must start with 'api'
333	  if (segments[0] !== 'api') return null;
334	
335	  const rest = segments.slice(1);
336	
337	  // Route dispatch note:
338	  // Routes are matched by segment count (rest.length) first, then by segment values.
339	  // Because the dispatcher walks the if-else chain in declaration order, two routes
340	  // that share the same rest.length value are ordered by their position here — the
341	  // first matching branch wins and subsequent branches at the same length are shadowed.
342	  // When adding a new route with the same rest.length as an existing one (e.g. a future
343	  // /:slug/synthesis at length 3 alongside /:slug/plan), make sure the more-specific
344	  // pattern appears BEFORE the catch-all pattern at that length, or it will never match.
345	
346	  // GET /api/insights
347	  if (method === 'GET' && rest.length === 1 && rest[0] === 'insights') {
348	    return () => handleGetInsights(ledgerRoot);
349	  }
350	
351	  // GET /api/orchestrator/queue
352	  if (method === 'GET' && rest.length === 2 && rest[0] === 'orchestrator' && rest[1] === 'queue') {
353	    return () => handleGetOrchestratorQueue(orchestratorLogsDir, ledgerRoot);
354	  }
355	
356	  // GET /api/orchestrator/run-status/:filename
357	  if (method === 'GET' && rest.length === 3 && rest[0] === 'orchestrator' && rest[1] === 'run-status') {
358	    const filename = decodeURIComponent(rest[2]!);
359	    return () => handleGetRunStatus(orchestratorLogsDir, filename);
360	  }
361	
362	  // GET /api/projects
363	  if (method === 'GET' && rest.length === 1 && rest[0] === 'projects') {
364	    const qIdx = url.indexOf('?');
365	    const qStr = qIdx !== -1 ? url.slice(qIdx + 1) : '';
366	    const sp = new URLSearchParams(qStr);
367	    const params = {
368	      page: sp.get('page') ?? undefined,
369	      limit: sp.get('limit') ?? undefined,
370	      status: sp.get('status') ?? undefined,
371	      search: sp.get('search') ?? undefined,
372	      sort: sp.get('sort') ?? undefined,
373	      dir: sp.get('dir') ?? undefined,
374	      runner: sp.get('runner') ?? undefined,
375	    };
376	    return () => handleListProjects(ledgerRoot, params);
377	  }
378	
379	  // GET /api/projects/:slug/plan
380	  if (
381	    method === 'GET' &&
382	    rest.length === 3 &&
383	    rest[0] === 'projects' &&
384	    rest[2] === 'plan'
385	  ) {
386	    const slug = rest[1]!;
387	    return () => handleGetPlanDocument(ledgerRoot, slug);
388	  }
389	
390	  // GET /api/projects/:slug/synthesis
391	  if (
392	    method === 'GET' &&
393	    rest.length === 3 &&
394	    rest[0] === 'projects' &&
395	    rest[2] === 'synthesis'
396	  ) {
397	    const slug = rest[1]!;
398	    return () => handleGetSynthesisDocument(ledgerRoot, slug);
399	  }
400	
401	  // GET /api/projects/:slug/health
402	  if (
403	    method === 'GET' &&
404	    rest.length === 3 &&
405	    rest[0] === 'projects' &&
406	    rest[2] === 'health'
407	  ) {
408	    const slug = rest[1]!;
409	    return () => handleGetProjectHealth(ledgerRoot, slug);
410	  }
411	
412	  // GET /api/projects/:slug
413	  if (method === 'GET' && rest.length === 2 && rest[0] === 'projects') {
414	    const slug = rest[1]!;
415	    return () => handleGetProject(ledgerRoot, slug);
416	  }
417	
418	  // GET /api/projects/:slug/work-packages
419	  if (
420	    method === 'GET' &&
421	    rest.length === 3 &&
422	    rest[0] === 'projects' &&
423	    rest[2] === 'work-packages'
424	  ) {
425	    const slug = rest[1]!;
426	    return () => handleListWorkPackages(ledgerRoot, slug);
427	  }
428	
429	  // GET /api/projects/:slug/work-packages/overview
430	  // IMPORTANT: this route has rest.length === 4 and must appear BEFORE the
431	  // generic /:wpId handler at the same length, otherwise 'overview' would be
432	  // treated as a WP ID.
433	  if (
434	    method === 'GET' &&
435	    rest.length === 4 &&
436	    rest[0] === 'projects' &&
437	    rest[2] === 'work-packages' &&
438	    rest[3] === 'overview'
439	  ) {
440	    const slug = rest[1]!;
441	    return () => handleGetWorkPackageOverview(ledgerRoot, slug);
442	  }
443	
444	  // GET /api/projects/:slug/dialogues/:filename
445	  // rest.length === 4, rest[2] === 'dialogues' — must appear before the generic
446	  // work-packages/:wpId handler at the same length.
447	  if (
448	    method === 'GET' &&
449	    rest.length === 4 &&
450	    rest[0] === 'projects' &&
451	    rest[2] === 'dialogues'
452	  ) {
453	    const slug = rest[1]!;
454	    const filename = decodeURIComponent(rest[3]!);
455	    return () => handleGetDialogueFile(ledgerRoot, slug, filename);
456	  }
457	
458	  // GET /api/projects/:slug/work-packages/:wpId
459	  if (
460	    method === 'GET' &&
461	    rest.length === 4 &&
462	    rest[0] === 'projects' &&
463	    rest[2] === 'work-packages'
464	  ) {
465	    const slug = rest[1]!;
466	    const wpId = rest[3]!;
467	    return () => handleGetWorkPackage(ledgerRoot, slug, wpId);
468	  }
469	
470	  // GET /api/projects/:slug/dialogues[?wp=WP-001]
471	  // rest.length === 3, rest[2] === 'dialogues' — does not shadow other rest[2] routes
472	  if (
473	    method === 'GET' &&
474	    rest.length === 3 &&
475	    rest[0] === 'projects' &&
476	    rest[2] === 'dialogues'
477	  ) {
478	    const slug = rest[1]!;
479	    const qIdx = url.indexOf('?');
480	    const qStr = qIdx !== -1 ? url.slice(qIdx + 1) : '';
481	    const sp = new URLSearchParams(qStr);
482	    const wpId = sp.get('wp') ?? undefined;
483	    return () => handleListDialogues(ledgerRoot, slug, wpId);
484	  }
485	
486	  // GET /api/projects/:slug/chunks
487	  // rest.length === 3, rest[2] === 'chunks' — analogous to the dialogues list route
488	  if (
489	    method === 'GET' &&
490	    rest.length === 3 &&
491	    rest[0] === 'projects' &&
492	    rest[2] === 'chunks'
493	  ) {
494	    const slug = rest[1]!;
495	    const qIdx = url.indexOf('?');
496	    const qStr = qIdx !== -1 ? url.slice(qIdx + 1) : '';
497	    const sp = new URLSearchParams(qStr);
498	    const wpId = sp.get('wp') ?? undefined;
499	    return () => handleListChunks(ledgerRoot, slug, wpId);
500	  }
501	
502	  // GET /api/projects/:slug/chunks/:filename/rendered
503	  // rest.length === 5, rest[2] === 'chunks', rest[4] === 'rendered'
504	  // Placement note: this route (rest.length === 5) and the raw-file route below
505	  // (rest.length === 4) have different segment counts, so there is no ordering
506	  // requirement between them — the dispatcher can never confuse the two.  This
507	  // block is placed here (before the length-4 route) solely to keep all three
508	  // chunk routes visually adjacent and in URL-specificity order.
509	  if (
510	    method === 'GET' &&
511	    rest.length === 5 &&
512	    rest[0] === 'projects' &&
513	    rest[2] === 'chunks' &&
514	    rest[4] === 'rendered'
515	  ) {
516	    const slug = rest[1]!;
517	    const filename = decodeURIComponent(rest[3]!);
518	    return () =>
519	      handleGetChunkFile(ledgerRoot, slug, filename).then(({ content }) => ({
520	        content: renderChunksToMarkdown(content),
521	      }));
522	  }
523	
524	  // GET /api/projects/:slug/chunks/:filename
