1135	async function serveStatic(
1136	  req: IncomingMessage,
1137	  res: ServerResponse,
1138	  port: number
1139	): Promise<void> {
1140	  const urlPath = (req.url ?? '/').split('?')[0]!;
1141	  const filePath =
1142	    urlPath === '/' ? join(PUBLIC_DIR, 'index.html') : join(PUBLIC_DIR, urlPath.slice(1));
1143	
1144	  // Security: prevent path traversal outside PUBLIC_DIR
1145	  const resolved = resolve(filePath);
1146	  if (!resolved.startsWith(PUBLIC_DIR)) {
1147	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1148	    return;
1149	  }
1150	
1151	  const ext = extname(filePath);
1152	  const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
1153	
1154	  try {
1155	    const content = await readFile(filePath);
1156	    res.writeHead(200, {
1157	      'Content-Type': mimeType,
1158	      'Content-Length': content.length,
1159	      'Cache-Control': 'no-store',
1160	      ...corsHeaders(port),
1161	      ...securityHeaders(),
1162	    });
1163	    res.end(content);
1164	  } catch {
1165	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1166	  }
1167	}
