1445	  const server = createServer((req, res) => {
1446	    handleRequest(req, res, ledgerRoot, configPath, port, orchestratorLogsDir, bootVersions).catch((err) => {
1447	      process.stderr.write(`[server] Unhandled error: ${String(err)}\n`);
1448	      if (!res.headersSent) {
1449	        res.writeHead(500, { 'Content-Type': 'application/json', ...securityHeaders() });
1450	        res.end(
1451	          JSON.stringify({
1452	            error: { code: 'INTERNAL_ERROR', message: 'An unexpected error occurred.' },
1453	          })
1454	        );
1455	      }
1456	    });
1457	  });
1458	
1459	  server.on('error', (err: NodeJS.ErrnoException) => {
1460	    if (err.code === 'EADDRINUSE') {
1461	      process.stderr.write(
1462	        `[server] Port ${port} is already in use. Choose a different port with --port <n>. Exiting.\n`
1463	      );
1464	      process.exit(1);
1465	    }
1466	    throw err;
1467	  });
1468	
1469	  server.listen(port, () => {
1470	    console.log(`GUI dashboard running at http://localhost:${port}`);
1471	  });
1472	}
1473	
1474	// Only run main() when this file is the entry point (e.g. `tsx gui/server.ts`),
1475	// not when it is imported by test code (e.g. to access the exported handleRequest).
1476	const isEntryPoint =
1477	  process.argv[1] !== undefined &&
1478	  fileURLToPath(import.meta.url) === resolve(process.argv[1]);
